def check_ratings(n, ratings):
    sorted_ratings = sorted(ratings, key=lambda x: (-x[1], x[0]))
    original_positions = {rating[0]: i for i, rating in enumerate(ratings)}
    new_positions = {sorted_rating[0]: i for i, sorted_rating in enumerate(sorted_ratings)}

    if len(set(new_positions.values())) != n:
        return "maybe"

    for i in range(1, n):
        if new_positions[ratings[i][0]] > new_positions[ratings[i-1][0]]:
            return "maybe"

    if any(original_positions[rating[0]] != new_positions[rating[0]] for rating in ratings):
        return "rated"
    else:
        return "unrated"

